using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Headless.XUnit;
using Avalonia.Media.Imaging;
using Avalonia.Threading;
using Avalonia.VisualTree;
using BacklogManager.Controls;
using BacklogManager.Data;
using BacklogManager.Models;
using BacklogManager.Services;
using Xunit;

namespace BacklogManager.Tests.Fase3;

public sealed class InteracaoBibliotecaTests
{
    private static BacklogItem[] Registros() => new[] { ConsultasTests.Item(data: new DateTimeOffset(2026, 10, 20, 12, 0, 0, TimeSpan.Zero)), ConsultasTests.Item("Beta", 2, "Aventura", "Switch") }.Select(ConversorBibliotecaJson.ParaRegistro).ToArray();
    private static void Renderizar(TelaTeste t) { t.Clicar("NavBacklog"); Dispatcher.UIThread.RunJobs(); t.Janela.UpdateLayout(); }
    [AvaloniaFact(DisplayName = "IB01 | Preferência padrão na janela | Grade inicial sem criar preferência ou regravar biblioteca")]
    public void Padrao() { using var p = new PastaTeste(); var pref = new ArmazenamentoPreferenciasBiblioteca(Path.Combine(p.Pasta, "preferencias.json")); using var t = new TelaTeste(Registros(), preferencias: pref); var original = File.ReadAllBytes(t.Pasta.Arquivo); Renderizar(t); Assert.Equal(0, t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex); Assert.False(File.Exists(pref.CaminhoArquivo)); Assert.Equal(original, File.ReadAllBytes(t.Pasta.Arquivo)); }
    [AvaloniaFact(DisplayName = "IB02 | Preferência de lista ao abrir | Lista recuperada pela janela")]
    public void PreferenciaLista() { using var p = new PastaTeste(); var pref = new ArmazenamentoPreferenciasBiblioteca(Path.Combine(p.Pasta, "preferencias.json")); pref.Salvar(VisualizacaoBiblioteca.Lista); using var t = new TelaTeste(Registros(), preferencias: pref); Assert.Equal(1, t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex); }
    [AvaloniaFact(DisplayName = "IB03 | Alternar e reabrir janela | Preferência persiste sem tocar a biblioteca")]
    public void Reiniciar() { using var p = new PastaTeste(); var caminho = Path.Combine(p.Pasta, "preferencias.json"); using (var t = new TelaTeste(Registros(), preferencias: new(caminho))) { var original = File.ReadAllBytes(t.Pasta.Arquivo); t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex = 1; Assert.Equal(original, File.ReadAllBytes(t.Pasta.Arquivo)); } using var nova = new TelaTeste(Registros(), preferencias: new(caminho)); Assert.Equal(1, nova.Campo<ComboBox>("CmbVisualizacao").SelectedIndex); }
    [AvaloniaFact(DisplayName = "IB04 | Preferência corrompida na janela | Aviso, grade e biblioteca utilizável")]
    public void PrefCorrompida() { using var p = new PastaTeste(); var caminho = Path.Combine(p.Pasta, "preferencias.json"); File.WriteAllText(caminho, "{"); using var t = new TelaTeste(Registros(), preferencias: new(caminho)); Assert.Equal(0, t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex); Assert.Contains("grade", t.Aviso); Assert.Equal(2, t.Exibidos.Length); Assert.Equal("{", File.ReadAllText(caminho)); }
    [AvaloniaFact(DisplayName = "IB05 | Falha ao guardar visualização | Modo muda na sessão e CRUD continua permitido")]
    public void FalhaPreferencia() { using var p = new PastaTeste(); var caminho = Path.Combine(p.Pasta, "preferencias.json"); Directory.CreateDirectory(caminho); using var t = new TelaTeste(Registros(), preferencias: new(caminho)); t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex = 1; Assert.Equal(1, t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex); Assert.Contains("sessão", t.Aviso); t.Selecionar(99); t.Clicar("BtnAdicionar"); Assert.Equal(3, t.Salvos.Count); }
    [AvaloniaFact(DisplayName = "IB06 | Filtro de plataforma | Apenas jogo da plataforma selecionada aparece")]
    public void Plataforma() { using var t = new TelaTeste(Registros()); t.Campo<ComboBox>("CmbPlataforma").SelectedItem = "Switch"; Assert.Equal("Beta", Assert.Single(t.Exibidos).Titulo); }
    [AvaloniaFact(DisplayName = "IB07 | Legado sem plataforma | Controle desabilitado e registro permanece disponível")]
    public void PlataformaLegado() { using var t = new TelaTeste(new[] { PastaTeste.Jogo() }); Assert.False(t.Campo<ComboBox>("CmbPlataforma").IsEnabled); Assert.Single(t.Exibidos); }
    [AvaloniaFact(DisplayName = "IB08 | Trocar para mídia sem plataforma | Opções antigas são limpas e plataforma desabilitada")]
    public void TrocarTipo() { using var t = new TelaTeste(Registros()); t.Campo<ComboBox>("CmbPlataforma").SelectedItem = "PC"; t.Campo<ComboBox>("CmbTipoBiblioteca").SelectedIndex = (int)TipoMidia.Livro; Assert.False(t.Campo<ComboBox>("CmbPlataforma").IsEnabled); Assert.Equal(0, t.Campo<ComboBox>("CmbPlataforma").SelectedIndex); Assert.Empty(t.Exibidos); }
    [AvaloniaFact(DisplayName = "IB09 | Filtro de data conhecido | Legado sem data é excluído somente com filtro ativo")]
    public void Data() { using var t = new TelaTeste(Registros()); t.Campo<CalendarDatePicker>("DataAdicaoDe").SelectedDate = new DateTime(2026, 10, 1); Dispatcher.UIThread.RunJobs(); Assert.Equal("Alfa", Assert.Single(t.Exibidos).Titulo); t.Campo<CalendarDatePicker>("DataAdicaoDe").SelectedDate = null; Dispatcher.UIThread.RunJobs(); Assert.Equal(2, t.Exibidos.Length); }
    [AvaloniaFact(DisplayName = "IB10 | Datas invertidas na janela | Aviso claro sem perder resultado e recuperação ao corrigir")]
    public void DatasInvalidas() { using var t = new TelaTeste(Registros()); t.Campo<CalendarDatePicker>("DataAdicaoDe").SelectedDate = new DateTime(2026, 10, 22); t.Campo<CalendarDatePicker>("DataAdicaoAte").SelectedDate = new DateTime(2026, 10, 20); Dispatcher.UIThread.RunJobs(); Assert.True(t.Campo<TextBlock>("TxtErroFiltros").IsVisible); t.Clicar("BtnLimparFiltros"); Assert.False(t.Campo<TextBlock>("TxtErroFiltros").IsVisible); Assert.Equal(2, t.Exibidos.Length); }
    [AvaloniaFact(DisplayName = "IB11 | Alternar com filtros ativos | Consulta e ordenação permanecem nas duas visualizações")]
    public void PreservarFiltros() { using var t = new TelaTeste(Registros()); t.Campo<ComboBox>("CmbGenero").SelectedItem = "RPG"; t.Campo<ComboBox>("CmbOrdenacao").SelectedIndex = 3; t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex = 1; Assert.Equal("Alfa", Assert.Single(t.Exibidos).Titulo); Assert.Equal("RPG", t.Campo<ComboBox>("CmbGenero").SelectedItem); Assert.Equal(3, t.Campo<ComboBox>("CmbOrdenacao").SelectedIndex); }
    [AvaloniaFact(DisplayName = "IB12 | Ordenar com item selecionado | Mesma instância continua selecionada no novo índice")]
    public void PreservarSelecao() { using var t = new TelaTeste(Registros()); var lista = t.Campo<ListBox>("ListaBacklog"); lista.SelectedIndex = 0; var item = lista.SelectedItem; t.Campo<ComboBox>("CmbOrdenacao").SelectedIndex = 2; Assert.Same(item, lista.SelectedItem); Assert.Equal(1, lista.SelectedIndex); }
    [AvaloniaFact(DisplayName = "IB13 | Filtro oculta seleção | Ações são desabilitadas e registros não são removidos")]
    public void OcultarSelecao() { using var t = new TelaTeste(Registros()); t.Campo<ListBox>("ListaBacklog").SelectedIndex = 0; t.Campo<TextBox>("TxtBusca").Text = "ausente"; Dispatcher.UIThread.RunJobs(); Assert.Empty(t.Exibidos); Assert.False(t.Campo<Button>("BtnRemover").IsEnabled); Assert.Equal(2, t.Salvos.Count); }
    [AvaloniaFact(DisplayName = "IB14 | Filtros expandidos no tamanho mínimo | Controles e rodapé permanecem acessíveis")]
    public void FiltrosMinimos() { using var t = new TelaTeste(Registros()); t.Janela.Width = 900; t.Janela.Height = 660; t.Campo<Expander>("FiltrosAvancados").IsExpanded = true; Renderizar(t); Assert.True(t.Campo<ListBox>("ListaBacklog").Bounds.Height > 90); Assert.True(t.Campo<Button>("BtnRemover").Bounds.Height > 20); var pasta = Path.Combine(Path.GetTempPath(), "backlogmanager-ajustes-fase3-resultados", "visualizacoes"); Directory.CreateDirectory(pasta); using var frame = t.Janela.CaptureRenderedFrame(); Assert.NotNull(frame); frame.Save(Path.Combine(pasta, "filtros-minimo.png"), PngBitmapEncoderOptions.Default); }
    [AvaloniaFact(DisplayName = "IB15 | Legado sem capa na grade | Imagem padrão renderizada com título preservado")]
    public void PadraoCapa() { using var t = new TelaTeste(new[] { PastaTeste.Jogo() }); Renderizar(t); var textos = t.Campo<ListBox>("ListaBacklog").GetVisualDescendants().OfType<TextBlock>().Select(c => c.Text).ToArray(); Assert.Contains("Sem capa", textos); Assert.Contains("Jogo simulado", textos); }
    [AvaloniaFact(DisplayName = "IB16 | Capa de sugestão simulada | Desenho local carregado e aviso de simulação visível")]
    public async Task Sugestoes() { using var t = new TelaTeste(); t.Clicar("NavCadastro"); t.Campo<ComboBox>("CmbTipoCadastro").SelectedIndex = (int)TipoMidia.Livro; t.Campo<TextBox>("TxtTitulo").Text = "simulado"; await Dispatcher.UIThread.InvokeAsync(() => { }, DispatcherPriority.Background); await t.Janela.BuscaPendente.WaitAsync(TimeSpan.FromSeconds(5), TestContext.Current.CancellationToken); Dispatcher.UIThread.RunJobs(); t.Janela.UpdateLayout(); var capas = t.Campo<ListBox>("ListaSugestoes").GetVisualDescendants().OfType<CapaObra>().ToArray(); Assert.NotEmpty(capas); await Task.WhenAll(capas.Select(c => c.CarregamentoPendente)); Assert.All(capas, capa => Assert.Contains(capa.GetVisualDescendants().OfType<Image>(), i => i.Source != null)); Assert.Equal(0, t.Http.Chamadas); }
    [AvaloniaFact(DisplayName = "IB17 | Limpar preferência inválida pela janela | Troca deliberada salva nova escolha")]
    public void RecuperarPref() { using var p = new PastaTeste(); var caminho = Path.Combine(p.Pasta, "pref.json"); File.WriteAllText(caminho, "inválida"); using var t = new TelaTeste(preferencias: new(caminho)); t.Campo<ComboBox>("CmbVisualizacao").SelectedIndex = 1; Assert.Equal(VisualizacaoBiblioteca.Lista, new ArmazenamentoPreferenciasBiblioteca(caminho).Carregar()); }
    [AvaloniaFact(DisplayName = "IB18 | Grade com várias obras | Cartões se distribuem em linhas sem rolagem horizontal")]
    public void QuebraLinha() { using var t = new TelaTeste(Enumerable.Range(0, 6).Select(n => PastaTeste.Jogo("Obra " + n))); t.Janela.Width = 900; t.Janela.Height = 660; Renderizar(t); var lista = t.Campo<ListBox>("ListaBacklog"); var itens = lista.GetVisualDescendants().OfType<ListBoxItem>().ToArray(); Assert.Equal(6, itens.Length); Assert.True(itens[3].Bounds.Y > itens[0].Bounds.Y); Assert.True(itens[2].Bounds.Right < lista.Bounds.Width); }
    private const string Url = "https://images.igdb.com/igdb/image/upload/t_cover_big/tela.jpg";
    private static CapaObra Capa(TelaTeste t) => t.Campo<ListBox>("ListaBacklog").GetVisualDescendants().OfType<CapaObra>().First();
    private static BacklogItem RegistroCapa() { var i = ConsultasTests.Item(); return ConversorBibliotecaJson.ParaRegistro(i with { Catalogo = i.Catalogo with { CapaUrl = Url } }); }
    [AvaloniaFact(DisplayName = "IB19 | Capa remota simulada no cartão | Bitmap aparece após carregamento assíncrono")]
    public async Task CapaRemota() { var png = CapasTests.Png(); using var h = new HttpSimulado { Responder = (_, _) => Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent(png) }) }; using var c = new HttpClient(h); using var t = new TelaTeste(new[] { RegistroCapa() }, capas: new CarregadorCapas(c)); Renderizar(t); var capa = Capa(t); await capa.CarregamentoPendente; Assert.Contains(capa.GetVisualDescendants().OfType<Image>(), i => i.Source is Bitmap && i.IsVisible); Assert.Equal(1, h.Chamadas); }
    [AvaloniaFact(DisplayName = "IB20 | Falha de capa no cartão | Imagem padrão e ações locais disponíveis")]
    public async Task CapaFalha() { using var h = new HttpSimulado { Responder = (_, _) => throw new HttpRequestException("offline") }; using var c = new HttpClient(h); using var t = new TelaTeste(new[] { RegistroCapa() }, capas: new CarregadorCapas(c)); Renderizar(t); var capa = Capa(t); await capa.CarregamentoPendente; Assert.Contains(capa.GetVisualDescendants().OfType<TextBlock>(), b => b.Text == "Sem capa" && b.IsVisible); t.Campo<ListBox>("ListaBacklog").SelectedIndex = 0; Assert.True(t.Campo<Button>("BtnEditar").IsEnabled); }
    [AvaloniaFact(DisplayName = "IB21 | Referência muda durante download | Resposta antiga não substitui a nova capa")]
    public async Task CapaAntiga() { var png = CapasTests.Png(); var liberar = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); using var h = new HttpSimulado { Responder = async (_, ct) => { await liberar.Task.WaitAsync(ct); return new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new ByteArrayContent(png) }; } }; using var c = new HttpClient(h); using var t = new TelaTeste(new[] { RegistroCapa() }, capas: new CarregadorCapas(c)); Renderizar(t); var capa = Capa(t); var antiga = capa.CarregamentoPendente; capa.Endereco = "avares://BacklogManager/Assets/CapasSimuladas/Livro.svg"; await capa.CarregamentoPendente; liberar.SetResult(); await antiga; Assert.Contains(capa.GetVisualDescendants().OfType<Image>(), i => i.Source is Avalonia.Media.DrawingImage); }
    [AvaloniaFact(DisplayName = "IB22 | Cartão removido durante download | Carga visual é cancelada sem falha na exclusão")]
    public async Task CapaRemovida() { var entrou = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); using var h = new HttpSimulado { Responder = async (_, ct) => { entrou.TrySetResult(); await Task.Delay(System.Threading.Timeout.InfiniteTimeSpan, ct); return new HttpResponseMessage(); } }; using var c = new HttpClient(h); using var t = new TelaTeste(new[] { RegistroCapa() }, capas: new CarregadorCapas(c)); Renderizar(t); await entrou.Task.WaitAsync(TimeSpan.FromSeconds(5), TestContext.Current.CancellationToken); var pendente = Capa(t).CarregamentoPendente; t.Campo<ListBox>("ListaBacklog").SelectedIndex = 0; t.Clicar("BtnRemover"); Renderizar(t); await pendente.WaitAsync(TimeSpan.FromSeconds(5), TestContext.Current.CancellationToken); Assert.Empty(t.Salvos); }
}
